-- GoTrue (Supabase Auth) needs an identity row for email/password sign-in.
do $$
begin
  if to_regclass('auth.identities') is not null then
    execute $q$
      select gen_random_uuid(), u.id, u.id::text, 'email',
             jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true), now(), now(), now()
        from auth.users u
       where u.email like '%@alrowad.sa' or u.email like '%@alnukhba.sa' or u.email = 'ops@busna.sa'
    $q$;
  end if;
end $$;

select id, raw_user_meta_data ->> 'full_name', public.normalize_phone(phone) from auth.users
on conflict (id) do nothing;


